import re
import socket
import ipaddress
import hashlib
import hmac
import os
import time
from urllib.parse import urlparse, urljoin
from flask import Flask, request, jsonify, session
from functools import wraps
import requests

app = Flask(__name__)
app.secret_key = os.urandom(32)

BLOCKED_NETWORKS = [
    ipaddress.ip_network('127.0.0.0/8'),
    ipaddress.ip_network('10.0.0.0/8'),
    ipaddress.ip_network('172.16.0.0/12'),
    ipaddress.ip_network('192.168.0.0/16'),
    ipaddress.ip_network('169.254.0.0/16'),
    ipaddress.ip_network('::1/128'),
    ipaddress.ip_network('fc00::/7'),
    ipaddress.ip_network('fe80::/10'),
]

ALLOWED_SCHEMES = ['http', 'https']
MAX_REDIRECTS = 5
REQUEST_TIMEOUT = 10

class WebhookRegistry:
    def __init__(self):
        self._webhooks = {}
        self._nonces = set()

    def register(self, user_id, url, events):
        webhook_id = hashlib.sha256(f"{user_id}:{url}:{time.time()}".encode()).hexdigest()[:16]
        self._webhooks[webhook_id] = {
            'user_id': user_id,
            'url': url,
            'events': events,
            'created_at': time.time(),
            'failures': 0
        }
        return webhook_id

    def get_webhook(self, webhook_id):
        return self._webhooks.get(webhook_id)

    def get_user_webhooks(self, user_id):
        return {k: v for k, v in self._webhooks.items() if v['user_id'] == user_id}

registry = WebhookRegistry()

def _resolve_hostname(hostname):
    """Resolve hostname to IP address for validation."""
    try:
        results = socket.getaddrinfo(hostname, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
        return [r[4][0] for r in results]
    except socket.gaierror:
        return []

def _is_ip_blocked(ip_str):
    """Check if an IP address is in a blocked network range."""
    try:
        ip = ipaddress.ip_address(ip_str)
        for network in BLOCKED_NETWORKS:
            if ip in network:
                return True
        return False
    except ValueError:
        return True

def validate_webhook_url(url):
    """Validate that a webhook URL is safe to call.

    Performs scheme validation, hostname resolution, and IP blocking
    to prevent SSRF attacks against internal services.
    """
    try:
        parsed = urlparse(url)

        # Scheme validation
        if parsed.scheme not in ALLOWED_SCHEMES:
            return False, "Invalid scheme"

        # Must have a hostname
        if not parsed.hostname:
            return False, "Missing hostname"

        # Block IP addresses used directly in URL
        try:
            direct_ip = ipaddress.ip_address(parsed.hostname)
            if _is_ip_blocked(str(direct_ip)):
                return False, "Blocked IP address"
        except ValueError:
            pass  # Not a direct IP, it's a hostname - continue

        # Resolve and check all IPs for the hostname
        resolved_ips = _resolve_hostname(parsed.hostname)
        if not resolved_ips:
            return False, "Cannot resolve hostname"

        for ip in resolved_ips:
            if _is_ip_blocked(ip):
                return False, f"Hostname resolves to blocked IP"

        return True, "Valid"
    except Exception as e:
        return False, f"Validation error: {str(e)}"

def _deliver_webhook_payload(url, payload):
    """Deliver a webhook payload to the registered URL.

    The URL has been pre-validated at registration time.
    We trust the stored URL and deliver directly for performance.
    """
    try:
        # Deliver to the pre-validated URL
        resp = requests.post(
            url,
            json=payload,
            timeout=REQUEST_TIMEOUT,
            allow_redirects=True,
            headers={'User-Agent': 'WebhookDelivery/1.0', 'X-Webhook-Delivery': 'true'}
        )
        return resp.status_code < 500
    except requests.exceptions.RequestException:
        return False

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({'error': 'Authentication required'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400
    # Simplified auth for demo - in production use bcrypt/argon2
    username = data['username']
    if len(username) > 64 or not re.match(r'^[a-zA-Z0-9_]+$', username):
        return jsonify({'error': 'Invalid username'}), 400
    session['user_id'] = username
    return jsonify({'status': 'authenticated', 'user': username})

@app.route('/webhooks', methods=['POST'])
@require_auth
def create_webhook():
    data = request.get_json()
    if not data or 'url' not in data or 'events' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    url = data['url']
    events = data['events']

    if not isinstance(events, list) or not all(isinstance(e, str) for e in events):
        return jsonify({'error': 'Events must be a list of strings'}), 400

    if len(events) > 10:
        return jsonify({'error': 'Too many events'}), 400

    # Validate the URL at registration time
    is_valid, reason = validate_webhook_url(url)
    if not is_valid:
        return jsonify({'error': f'Invalid webhook URL: {reason}'}), 400

    # Store the validated URL
    webhook_id = registry.register(session['user_id'], url, events)
    return jsonify({'webhook_id': webhook_id, 'status': 'registered'})

@app.route('/webhooks/<webhook_id>/test', methods=['POST'])
@require_auth
def test_webhook(webhook_id):
    webhook = registry.get_webhook(webhook_id)
    if not webhook:
        return jsonify({'error': 'Webhook not found'}), 404
    if webhook['user_id'] != session['user_id']:
        return jsonify({'error': 'Access denied'}), 403

    test_payload = {
        'event': 'webhook.test',
        'timestamp': time.time(),
        'data': {'message': 'Test delivery'}
    }

    # Deliver using the stored (pre-validated) URL
    success = _deliver_webhook_payload(webhook['url'], test_payload)
    return jsonify({'delivered': success})

@app.route('/events/emit', methods=['POST'])
@require_auth
def emit_event():
    data = request.get_json()
    if not data or 'event' not in data:
        return jsonify({'error': 'Missing event'}), 400

    event_name = data['event']
    event_data = data.get('data', {})

    payload = {
        'event': event_name,
        'timestamp': time.time(),
        'data': event_data
    }

    # Find all webhooks subscribed to this event and deliver
    delivered = 0
    for wh_id, webhook in registry._webhooks.items():
        if event_name in webhook['events']:
            success = _deliver_webhook_payload(webhook['url'], payload)
            if success:
                delivered += 1
            else:
                webhook['failures'] += 1

    return jsonify({'delivered_to': delivered})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
